export { view } from "../button";
export type { ButtonAttributes, ViewConfig } from "../button";

export {
  shadcnButtonClassName,
  shadcnDestructiveButtonClassName,
  shadcnSecondaryButtonClassName,
} from "./view";

export {
  buttonClassName as shadcnButtonClassName,
  destructiveButtonClassName as shadcnDestructiveButtonClassName,
  secondaryButtonClassName as shadcnSecondaryButtonClassName,
} from "../button/view";

import { describe, expect, test } from "vitest";

import * as Button from "./index";

describe("shadcn Button registry view", () => {
  test("reuses the Foldkit Button functional contract", () => {
    expect(Button.view).toBeTypeOf("function");
    expect(Button.shadcnButtonClassName).toContain("rounded");
    expect(Button.shadcnDestructiveButtonClassName).toContain("red");
  });
});
